  adapter: openai({ apiKey: KEY, model: 'gpt-4o' }),
  observers: [
    costGuard({
      budgetUsd: 0.10,
      controller,
      onCost: ({ costUsd, budgetRemainingUsd }) =>
        process.stdout.write(
