// 2. Chunk (simple: paragraphs of 500-ish chars)
function chunk(text: string, size = 500): string[] {
  const paragraphs = text.split(/\n\n+/)
  const chunks: string[] = []
  let current = ''
  for (const p of paragraphs) {
    if ((current + p).length > size) {
      if (current) chunks.push(current)
      current = p
    } else {
      current += '\n\n' + p
    }
  }
  if (current) chunks.push(current)
  return chunks
}

